package ru.krug.backend.plugin.application.port;

/**
 * Object storage for plugin package assets. Keys are generated by the application and
 * contain only the plugin id, version, install id and a validated relative path.
 */
public interface PluginAssetStoragePort {

    void put(String objectKey, byte[] content, String contentType);

    /** Reads at most {@code maxBytes}; a larger stored object is an error. */
    byte[] read(String objectKey, long maxBytes);

    void delete(String objectKey);
}
